<?php require 'includes/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $id=$_POST['id']??''; $action=$_POST['action']??''; if($action==='add'&&isset($products[$id])) $_SESSION['cart'][$id]=min(20,(int)($_SESSION['cart'][$id]??0)+1); if($action==='remove'&&isset($_SESSION['cart'][$id])) unset($_SESSION['cart'][$id]); if($action==='update'){foreach($_POST['qty']??[] as $key=>$qty)if(isset($products[$key])){if((int)$qty<=0)unset($_SESSION['cart'][$key]);else $_SESSION['cart'][$key]=min(20,(int)$qty);}} header('Location: cart.php');exit;} $title='Indkøbskurv';pageHeader($title);$sum=0; ?>
<main id="main"><section class="page-intro"><p class="eyebrow">DIT VALG</p><h1>Indkøbs<em>kurv.</em></h1></section><section class="section cart-section"><?php if(empty($_SESSION['cart'])): ?><p>Din kurv er stadig tom.</p><a class="button" href="products.php">Find din næste duft</a><?php else: ?><form method="post"><input type="hidden" name="action" value="update"><div class="cart-list"><?php foreach($_SESSION['cart'] as $id=>$qty): if(!isset($products[$id]))continue;$p=$products[$id];$line=$p['price']*$qty;$sum+=$line; ?><article class="cart-item"><img src="<?= e($p['image']) ?>" alt=""><div><h2><?= e($p['name']) ?></h2><p><?= money($p['price']) ?></p></div><label>Antal <input type="number" name="qty[<?= e($id) ?>]" min="0" max="20" value="<?= (int)$qty ?>"></label><strong><?= money($line) ?></strong><button formaction="cart.php" formmethod="post" name="id" value="<?= e($id) ?>" class="text-link" onclick="this.form.elements.namedItem('action').value='remove';this.form.elements.namedItem('id').value=this.value">Fjern</button></article><?php endforeach ?></div><div class="cart-total"><span>I alt</span><strong><?= money($sum) ?></strong></div><p class="fine-print">Fragt beregnes ved bestilling. Betaling er ikke aktiveret i denne demo.</p><button class="button">Opdatér kurv</button></form><?php endif ?></section></main><?php pageFooter(); ?>

